H.background();
const m = P.m, vmax = P.v;
const v = vmax * (0.5 - 0.5 * Math.cos(t * 1.1));
const KE = 0.5 * m * v * v;
const w = H.W, h = H.H;
const y0 = h * 0.55;
const x0 = w * 0.1, x1 = w * 0.9;
H.line(x0, y0 + 22, x1, y0 + 22, { color: H.colors.axis, width: 2 });
const frac = 0.5 - 0.5 * Math.cos(t * 1.1);
const bx = x0 + (x1 - x0) * frac;
const r = 12 + m * 1.5;
H.circle(bx, y0, r, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
const dir = Math.sin(t * 1.1) >= 0 ? 1 : -1;
const aL = 8 + v * 10;
H.arrow(bx, y0, bx + dir * aL, y0, { color: H.colors.warn, width: 4, head: 11 });
H.text("v", bx + dir * aL + dir * 8, y0 - 6, { color: H.colors.warn, size: 13, align: dir > 0 ? "left" : "right" });
const KEmax = 0.5 * m * vmax * vmax || 1;
const barX = w * 0.86, barTop = h * 0.18, barH = h * 0.5;
H.rect(barX, barTop, 26, barH, { stroke: H.colors.grid, width: 1.5 });
const fillH = barH * H.clamp(KE / KEmax, 0, 1);
H.rect(barX, barTop + barH - fillH, 26, fillH, { fill: H.colors.good });
H.text("KE", barX + 2, barTop - 8, { color: H.colors.sub, size: 12 });
H.text("Kinetic energy:  KE = ½ m v²", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(1) + " kg    v = " + v.toFixed(2) + " m/s    KE = " + KE.toFixed(1) + " J", 24, 54, { color: H.colors.sub, size: 14 });
